/// Borrows owned arrays as the [`WeightArray`] list `linear_init` binds from.
#[must_use]
pub fn as_weight_arrays(arrays: &[OwnedWeightArray]) -> Vec<WeightArray<'_>> {
    arrays
        .iter()
        .map(|(name, type_, data)| WeightArray {
            name: name.as_bytes(),
            type_: *type_,
            // The arrays are a few KiB: the size always fits.
            size: data.len() as i32,
            data,
        })
        .collect()
}

/// `LossGen`: the layers of the loss generator model.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct LossGen {
    pub lossgen_dense_in: LinearLayer,
    pub lossgen_dense_out: LinearLayer,
    pub lossgen_gru1_input: LinearLayer,
    pub lossgen_gru1_recurrent: LinearLayer,
    pub lossgen_gru2_input: LinearLayer,
    pub lossgen_gru2_recurrent: LinearLayer,
}

/// Port of the generated dnn/lossgen_data.c:init_lossgen (fails with `BadArg` where C returns
/// 1).
pub fn init_lossgen(arrays: &[WeightArray<'_>]) -> Result<LossGen> {
    Ok(LossGen {
        lossgen_dense_in: linear_init(
            arrays,
            Some("lossgen_dense_in_bias"),
            None,
            None,
            Some("lossgen_dense_in_weights_float"),
            None,
            None,
            None,
            2,
            8,
        )?,
        lossgen_dense_out: linear_init(
            arrays,
            Some("lossgen_dense_out_bias"),
            None,
            None,
            Some("lossgen_dense_out_weights_float"),
            None,
            None,
            None,
            32,
            1,
        )?,
        lossgen_gru1_input: linear_init(
            arrays,
            Some("lossgen_gru1_input_bias"),
            Some("lossgen_gru1_input_subias"),
            Some("lossgen_gru1_input_weights_int8"),
            Some("lossgen_gru1_input_weights_float"),
            None,
            None,
            Some("lossgen_gru1_input_scale"),
            8,
            48,
        )?,
        lossgen_gru1_recurrent: linear_init(
            arrays,
            Some("lossgen_gru1_recurrent_bias"),
            Some("lossgen_gru1_recurrent_subias"),
            Some("lossgen_gru1_recurrent_weights_int8"),
            Some("lossgen_gru1_recurrent_weights_float"),
            None,
            None,
            Some("lossgen_gru1_recurrent_scale"),
            16,
            48,
        )?,
        lossgen_gru2_input: linear_init(
            arrays,
            Some("lossgen_gru2_input_bias"),
            Some("lossgen_gru2_input_subias"),
            Some("lossgen_gru2_input_weights_int8"),
            Some("lossgen_gru2_input_weights_float"),
            None,
            None,
            Some("lossgen_gru2_input_scale"),
            16,
            96,
        )?,
        lossgen_gru2_recurrent: linear_init(
            arrays,
            Some("lossgen_gru2_recurrent_bias"),
            Some("lossgen_gru2_recurrent_subias"),
            Some("lossgen_gru2_recurrent_weights_int8"),
            Some("lossgen_gru2_recurrent_weights_float"),
            None,
            None,
            Some("lossgen_gru2_recurrent_scale"),
            32,
            96,
        )?,
    })
}
